insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 1, 'In ABUA''s unit table, which unit is the crude unit, and what in the configuration marks it?', '["Naphtha reformer: naphtha is the first stream in every crude''s yield row.", "Crude distillation: it is the one unit whose feed column names no stream.", "Diesel hydrotreater: it is the unit the plan fills to 650000.00 bbl.", "None is marked: the plan treats every unit carrying a capacity as a crude unit."]'::jsonb, 1, 'A unit with no feed is the crude unit. Crude distillation has no feed stream, so it takes crude and its yields are the crude yields.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 2, 'The Naphtha reformer runs one barrel. What does it consume, and what does it make?', '["One barrel of crude, split by that crude''s own naphtha yield of 0.2300.", "0.8500 of a barrel of naphtha for each barrel of reformate made.", "One barrel of reformate feed, making naphtha 0.8500 and offgas 0.1000 from it.", "One barrel of naphtha, making reformate 0.8500 and offgas 0.1000."]'::jsonb, 3, 'A unit''s throughput consumes one barrel of its feed stream for each barrel it runs. The reformer''s feed is naphtha, and its yields are reformate 0.8500 and offgas 0.1000.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 3, 'Which two of ABUA''s streams does no crude yield at all?', '["Reformate and ulsd.", "Offgas and residue, which only units make from their feeds.", "Naphtha and gasoil, which the reformer and hydrotreater make.", "Kero and offgas, since the crude yields table marks both with a dash."]'::jsonb, 0, 'The crude yield table prints a dash under reformate and ulsd for every crude. Those streams exist only because the reformer and the hydrotreater make them.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 4, 'The Diesel hydrotreater''s capacity is typed as 0. Which readings does the plan print for that entry?', '["Hydrotreater throughput 666608.70, crude run 2082608.70 bbl, margin 7173508.35.", "Hydrotreater throughput 650000.00, crude run 2029032.26 bbl, margin 7077935.48.", "Hydrotreater throughput 0.00, crude run 735294.12 bbl, margin 424264.71.", "No readings: the plan is refused, because a capacity of zero reads as a missing entry."]'::jsonb, 2, 'A limit typed as 0 is a limit of zero, so the unit runs nothing and the refinery replans around it. The 666608.70 row is the blank entry and the 650000.00 row is the plan as typed.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 5, 'The hydrotreater''s capacity is left blank. What capacity does the plan report for it?', '["0.00, as for a capacity typed as 0.", "No limit, which the plan reports as the number Infinity.", "Null, since a blank box carries no figure.", "650000.00, the capacity the unit carried before the box was emptied."]'::jsonb, 1, 'A limit left blank is no limit. The plan reports the capacity of a blank unit as the number Infinity, which is what no limit means to the solver.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 6, 'What utilisation does the plan report for the hydrotreater typed as 0, and for the hydrotreater left blank?', '["0.00 percent for the typed zero, null for the blank.", "100.00 percent for the blank, since it runs all it wants, and null for the zero.", "Null for both.", "0.00 percent for both, because neither has a finite capacity to fill."]'::jsonb, 2, 'A utilisation needs a finite capacity above zero. A blank is no limit and a zero cannot be divided into, so the plan prints null in both cases.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 7, 'How far does the month''s margin move from the plan as typed when the hydrotreater is shut, and when its box is emptied?', '["-6653670.77 for the typed zero, and 95572.87 for the blank.", "95572.87 for the typed zero, and -6653670.77 for the blank.", "-6653670.77 for the typed zero, and -230175.48 for the blank.", "-3047230.44 for the typed zero, and 95572.87 for the blank."]'::jsonb, 0, 'The same box, emptied or zeroed, moves the month''s margin in opposite directions. -230175.48 belongs to the crude unit at 1900000 barrels and -3047230.44 to the Forcados cargo cancelled.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 8, 'A planner forgets to fill in what a barrel of Forcados (illustrative) costs. What status does ABUA''s plan come back with?', '["Status optimal, running all 1100000.00 bbl of Forcados as if it were free.", "Status unbounded, because the empty cost box is read as having no limit.", "Status optimal, with Forcados dropped and Bonny Light and Brass River run alone.", "Status invalid, with a sentence that names the Forcados cost as the missing input."]'::jsonb, 3, 'The rule for limits does not extend to money. The engine refuses with status invalid and the sentence "Missing the cost of Forcados (illustrative). Enter 0 where the value really is zero."'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 9, 'What happens to ABUA''s plan when a planner enters -1 in the Naphtha reformer''s capacity box?', '["A plan with the reformer shut, since any capacity at or below 0 means no throughput.", "It refuses: \"Naphtha reformer capacity must be zero or more; leave it blank for no limit.\"", "A plan with no limit on the reformer, since a negative capacity is read as blank.", "The status infeasible, because no throughput can sit below a capacity of -1."]'::jsonb, 1, 'A capacity below zero means nothing, so the input is invalid and refused. The sentence tells the planner to leave the box blank if no limit is meant.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 10, 'Which entries does planRefinery''s missing list carry when the Naphtha reformer''s operating cost and Jet A-1''s price are empty together?', '["One entry, the operating cost of Naphtha reformer, as the first empty box it meets.", "No entries: Jet A-1 is priced at 0 and reforming costs nothing, status optimal.", "Both of them, in one list: the operating cost of Naphtha reformer and the price of Jet A-1.", "One entry, the price of Jet A-1, since a product without a price makes the plan infeasible."]'::jsonb, 2, 'The refusal reads "Missing the operating cost of Naphtha reformer, the price of Jet A-1. Enter 0 where the value really is zero." and the engine returns the missing list with both entries.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 11, 'Read ABUA''s recipes and unit feeds. Where can a barrel of naphtha go?', '["Into Naphtha export at 72.5000, or into the Naphtha reformer as its feed.", "Into Gasoline at 111.0000, or into the reformer as feed.", "Into Naphtha export only; no ABUA unit takes naphtha as feed.", "Into the Diesel hydrotreater as its feed, or out as Naphtha export at 72.5000."]'::jsonb, 0, 'Naphtha export''s recipe is naphtha 1.0000, and the reformer''s feed is naphtha. Gasoline''s recipe is reformate, which only the reformer makes.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 12, 'Which of ABUA''s streams has neither a product recipe nor a unit to feed?', '["Residue, which no unit takes as its feed stream.", "Reformate, which is made by the reformer alone.", "Kero, whose only product is sold as Jet A-1 fuel.", "Offgas."]'::jsonb, 3, 'Offgas goes into no product and no unit consumes it, so it can only be surplus. Residue goes into Fuel oil, reformate into Gasoline and kero into Jet A-1.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 13, 'Every ABUA product carries a floor of 0.00. What does that floor mean for the month?', '["Every product is capped at zero.", "No product has to be made at all.", "The floors count as blank, so the ceilings are lifted too.", "The plan must sell at least one barrel of each product."]'::jsonb, 1, 'The floor is the least the month must sell and the ceiling the most it can. A floor of 0.00 obliges nothing, and each ceiling still limits the sale.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 14, 'A crude cargo is cancelled for the month. Which entry tells the plan so?', '["Its availability left blank, since the cargo now has no figure at all.", "Its cost typed as 0.", "Its availability typed as 0.", "Its cost left blank, so the engine drops the crude from the plan."]'::jsonb, 2, 'A limit typed as 0 is a limit of zero. A blank availability is no limit, and a blank cost is refused by name. The Forcados cargo cancelled is entered the same way, availability typed 0.'),
  ('refinery', 'intermediate', 'module', 'm01-the-configuration', 15, 'Bonny Light (illustrative) carries a gasoil yield of 0.3100. What kind of figure is that yield?', '["A mass fraction: 0.3100 of the weight of every barrel of Bonny Light comes out as gasoil.", "The share of the Diesel hydrotreater''s gasoil feed that Bonny Light supplies in the month.", "The fraction of each barrel of gasoil that the Diesel hydrotreater turns into ulsd.", "A volume fraction: each barrel of Bonny Light run makes 0.3100 of a barrel of gasoil."]'::jsonb, 3, 'Yields are volume fractions, and Bonny Light (illustrative)''s row prints gasoil 0.3100 beside naphtha 0.2300, kero 0.1500, residue 0.2800 and offgas 0.0300. The hydrotreater''s own yield on its gasoil feed is ulsd 0.9700.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 1, 'Once the plan finds a feedless unit, what constraint does it write for it?', '["A ceiling row: crude run below the reformer''s feed.", "A floor row: throughput at least the crude run.", "An equality row: crude run = crude unit throughput.", "Nothing extra; it is planned like any other unit."]'::jsonb, 2, 'Every barrel of crude runs through the feedless unit, by an equality row. Crude that is bought is crude that is distilled, no more and no less.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 2, 'ABUA''s plan prints its total crude beside the crude unit throughput. What do the two read?', '["2029032.26 bbl and 2029032.26 bbl, agreeing to the barrel: true.", "2029032.26 bbl of crude against 2600000.00 bbl, the unit''s capacity.", "2082608.70 bbl of crude against 2029032.26 bbl through the unit.", "2029032.26 bbl of crude beside 0.00 bbl through the unit."]'::jsonb, 0, 'Crude run and crude unit throughput are one number printed twice, from the crude table and the unit table. 2600000.00 is the capacity, and the 0.00 reading belongs to a configuration whose crude unit has a feed.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 3, 'Which change makes the crude unit''s own capacity the crude run?', '["The Forcados cargo cancelled: total crude 1747826.09, utilisation 67.22.", "A jet floor of 300000 and a fuel oil floor of 700000: total crude 2267857.14, utilisation 87.23.", "The hydrotreater capacity left blank: total crude 2082608.70, utilisation 80.10.", "The crude unit at 1900000 barrels for the month: total crude 1900000.00, utilisation 100.00."]'::jsonb, 3, 'With the crude unit''s capacity set at 1900000 barrels, the total crude reads 1900000.00 and the crude unit reads 100.00 percent. A limit on the crude unit is a limit on crude.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 4, 'What is the crude unit''s utilisation in ABUA''s plan as typed?', '["97.07 percent, the reading printed on the reformer''s row.", "78.04 percent.", "100.00 percent, the reading printed for the hydrotreater row.", "80.10 percent, the reading with the hydrotreater left blank."]'::jsonb, 1, 'The unit table prints Crude distillation at 2029032.26 bbl of 2600000.00 bbl, 78.04 percent. The crude unit is not full, and the plan does not list it as at capacity.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 5, 'What does the crude unit charge for ABUA''s month, and on which barrels?', '["1182264.52, at 2.9000 a barrel on naphtha fed.", "4888554.84, at 1.2500 on every product barrel.", "2536290.32, at 1.2500 a barrel on every barrel of crude.", "1170000.00, on the gasoil it sends onward."]'::jsonb, 2, 'The plan prints the crude unit operating cost for the month as 2536290.32, 1.2500 a barrel on every barrel of crude. 1182264.52 is the reformer''s charge and 4888554.84 all three units together.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 6, 'ABUA''s crude unit is given a feed stream that no crude makes. What does the plan print?', '["Crude unit throughput 0.00 beside a crude run of 2029032.26 bbl, and a margin of 9614225.81.", "A crude run of 0.00 bbl and a margin of 0.00, since no unit is left to distil the crude.", "The status infeasible, because the crude unit''s feed stream is never made by any crude.", "A refusal naming the crude unit''s feed, since no unit in the configuration is feedless."]'::jsonb, 0, 'The row is written only when some unit has no feed. The crude run still reads 2029032.26 bbl while the crude unit runs 0.00 bbl and costs 0.00, and the plan prints a margin of 9614225.81.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 7, 'The fed-crude-unit configuration prints a margin of 9614225.81. Which printed margin belongs to the same configuration as typed, with its crude unit feedless?', '["9614225.81 again, the fed unit with its capacity typed as 0.", "7173508.35, the hydrotreater left blank.", "6847760.00, the crude unit capped.", "7077935.48, the margin as typed."]'::jsonb, 3, 'The digest prints the fed configuration''s margin, 9614225.81, against 7077935.48 for the configuration as typed. 9614225.81 is also the fed configuration with that unit''s capacity typed as 0, and 7173508.35 and 6847760.00 are the hydrotreater left blank and the crude unit at 1900000 barrels.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 8, 'In the configuration whose crude unit has a feed, that unit''s capacity is then typed as 0. What happens to the margin?', '["It falls to 424264.71, as when a unit is shut for a turnaround.", "It stays at 9614225.81.", "It falls to 0.00, since a crude unit of zero capacity runs no crude.", "Nothing is returned, because a crude unit cannot be typed as 0."]'::jsonb, 1, 'The plan prints the same margin: true. A configuration whose crude unit is not feedless has no crude unit in the plan, and its capacity and operating cost bind nothing, so shutting it changes nothing.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 9, 'Which crude does ABUA''s plan run short of its availability?', '["Forcados (illustrative), at 77.6000 the lowest-cost crude on offer.", "Brass River (illustrative), the smallest availability.", "Bonny Light (illustrative), 329032.26 of 1500000.00 bbl.", "Bonny Light and Brass River together, both below their availability."]'::jsonb, 2, 'The plan lists crudes at their availability: Forcados (illustrative) and Brass River (illustrative). Bonny Light runs 329032.26 bbl against 1500000.00 bbl available.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 10, 'Two changes touch only the diesel hydrotreater. What does the crude unit''s utilisation read in each?', '["28.28 percent with it shut, 80.10 percent with it left blank.", "80.10 percent with it shut, 28.28 percent with it left blank.", "78.04 percent in both, since neither change touches the crude unit.", "67.22 percent with it shut, 87.23 percent with it left blank."]'::jsonb, 0, 'The crude unit''s utilisation is set by the whole plan. A downstream unit reaches back through the streams to the crude the month can use, and the crude unit runs exactly that.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 11, 'The Forcados cargo is cancelled, availability typed 0. What do the total crude and the crude unit utilisation read?', '["735294.12 bbl and 28.28 percent.", "1900000.00 bbl and 100.00 percent, the crude unit''s own limit.", "2029032.26 bbl and 78.04 percent, with Bonny Light filling in.", "1747826.09 bbl and 67.22 percent."]'::jsonb, 3, 'Forcados, which ran at its full availability, is typed 0, and the plan''s total crude reads 1747826.09 bbl with the crude unit at 67.22 percent. 735294.12 and 28.28 belong to the hydrotreater shut, and 1900000.00 and 100.00 to the crude unit at 1900000 barrels.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 12, 'A dashboard shows the hydrotreater typed as 0 at 0.00 percent utilisation. What does the plan itself report?', '["0.00 percent, the same reading.", "Null.", "28.28 percent, the utilisation of the crude unit in that change.", "100.00 percent, since the unit runs all that its capacity allows."]'::jsonb, 1, 'The plan divides throughput by capacity only when the capacity is finite and above zero. Typed as 0 there is nothing to divide by, so the plan prints null, and a page showing 0.00 percent shows something the plan did not say.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 13, 'Which unit does ABUA''s plan list as at capacity?', '["Naphtha reformer, at 97.07 percent of its capacity.", "Crude distillation, at 78.04 percent.", "Diesel hydrotreater, at 100.00 percent.", "The reformer and the hydrotreater, both near full."]'::jsonb, 2, 'Units at capacity: Diesel hydrotreater, throughput 650000.00 bbl of 650000.00 bbl. The reformer at 97.07 percent and the crude unit at 78.04 percent are not on the list.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 14, 'Why can no barrel of ABUA''s crude escape the crude unit''s 1.2500 a barrel?', '["The equality row sends every barrel of crude through the crude unit.", "The crude cost column already carries the 1.2500 in each price.", "Each product''s price has 1.2500 taken off before revenue.", "The crude unit''s capacity of 2600000.00 bbl exceeds the crude run."]'::jsonb, 0, 'Crude run equals crude unit throughput, so the crude unit''s operating cost falls on every barrel of crude. The crude cost column is each volume at its crude''s own cost and carries no unit charge.'),
  ('refinery', 'intermediate', 'module', 'm02-the-crude-unit-carries-every-barrel', 15, 'Read the crude unit column down ABUA''s three unit rows. What does it print?', '["True on all three rows, since every unit runs streams made from crude.", "True on Crude distillation, false on the reformer and the hydrotreater.", "True on Crude distillation and the reformer, the two running below capacity.", "False on all three, since the crude unit is written as a row of its own."]'::jsonb, 1, 'The unit table prints crude unit true on Crude distillation, the unit with no feed, and false on the Naphtha reformer and the Diesel hydrotreater, whose feeds are naphtha and gasoil.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 1, 'Which three terms make up ABUA''s margin of 7077935.48?', '["Revenue 172316812.90, less crude cost 160350322.58 and nothing else.", "Revenue 172316812.90, less crude cost 160350322.58, less unit operating cost 4888554.84.", "Revenue 172316812.90, less crude cost, unit operating cost, staff and insurance.", "Revenue less unit operating cost 4888554.84, with crude cost charged in the schedule and the fixed costs of the month."]'::jsonb, 1, 'The digest''s definition is margin = product revenue - crude cost - unit operating cost. Fixed costs, capital, tax and financing are not terms in it.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 2, 'What is the denominator of ABUA''s gross margin per barrel of crude, 3.4883?', '["The product volume sold.", "The crude unit''s capacity, 2600000.00 bbl.", "The throughputs of all three units, added together.", "The total crude, 2029032.26 bbl."]'::jsonb, 3, 'gross margin per barrel = margin / total crude. The denominator is crude and only crude, so the figure speaks for the barrel the refinery bought.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 3, 'Leaving the hydrotreater''s capacity blank changes ABUA''s margin by 95572.87. What change in gross margin per barrel is printed for that row?', '["-0.0438.", "0.1158, the row where the crude unit is held at 1900000 barrels.", "-2.9113, the row where the hydrotreater is typed as shut.", "-0.8736, the row with the jet and fuel oil floors."]'::jsonb, 0, 'The blank hydrotreater row prints a margin change of 95572.87 and a gross margin per barrel of 3.4445, a change of -0.0438, so the total rises while the ratio falls. 0.1158, -2.9113 and -0.8736 belong to the crude unit at 1900000 barrels, the hydrotreater shut and the two floors.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 4, 'Of ABUA''s five plan variants, which one leaves the month earning less in total yet shows each barrel of crude earning more?', '["The hydrotreater capacity left blank: margin change 95572.87, gross margin per barrel change -0.0438.", "The Forcados cargo cancelled: margin change -3047230.44, gross margin per barrel change -1.1822.", "The crude unit at 1900000 barrels for the month: margin change -230175.48, gross margin per barrel change 0.1158.", "The jet and fuel oil floors: margin change -1148089.05, gross margin per barrel change -0.8736."]'::jsonb, 2, 'The crude unit at 1900000 barrels prints a margin change of -230175.48 and a gross margin per barrel change of 0.1158, the one row where the margin falls and the ratio rises. The blank hydrotreater moves the other way, and the Forcados and floors rows lower both.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 5, 'Under which of the five changes does ABUA buy more crude than the plan as typed yet earn a smaller margin?', '["The diesel hydrotreater capacity left blank, no limit.", "The jet floor of 300000 and the fuel oil floor of 700000.", "The Forcados cargo cancelled, its availability typed as 0.", "The crude unit held at 1900000 barrels for the whole month."]'::jsonb, 1, 'Against 2029032.26 bbl as typed, the floors row prints total crude 2267857.14 bbl and a margin change of -1148089.05. The blank hydrotreater runs 2082608.70 bbl and gains 95572.87, and the Forcados row, 1747826.09 bbl, and the capped crude unit, 1900000.00 bbl, both run less crude.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 6, 'What does the offgas row of ABUA''s stream balance read?', '["Made 103638.71, consumed 0.00, placed 0.00, surplus 103638.71.", "Made 103638.71, consumed 103638.71 by the reformer as fuel, surplus 0.00.", "Made 103638.71, placed 103638.71 in Fuel oil, surplus 0.00.", "Made 103638.71, surplus 0.00, never below zero."]'::jsonb, 0, 'made - consumed by units - placed in products = surplus. Offgas has no recipe and no unit, so its whole make is the stream nobody found a home for.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 7, 'Naphtha export and Gasoil export both sell 0.00 bbl. What does the stream balance show about why?', '["Their ceilings of 200000.00 and 250000.00 bbl are reached.", "Their floors of 0.00 forbid any sale.", "Neither product has a recipe naming a stream.", "Naphtha 407677.42 and gasoil 650000.00 are made and consumed in full by their units."]'::jsonb, 3, 'Naphtha made 407677.42 bbl and the reformer consumed 407677.42 bbl; gasoil made 650000.00 bbl and the hydrotreater consumed 650000.00 bbl. Nothing is left to place in the export products.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 8, 'How many of ABUA''s six products does the plan show at their ceiling?', '["One, Diesel (ULSD).", "One, Gasoline.", "None: every row reads false.", "Two, Jet A-1 and Fuel oil."]'::jsonb, 2, 'The product table''s at its ceiling column reads false on all six rows. Diesel (ULSD) sells 630500.00 of 750000.00 bbl and Gasoline 346525.81 of 450000.00 bbl, so no market holds the month back.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 9, 'Bonny Light (illustrative) runs 329032.26 of 1500000.00 bbl. Which limit named in the plan''s lists holds the crude run there?', '["The crude unit''s capacity of 2600000.00 bbl.", "Bonny Light''s own availability.", "The Diesel hydrotreater, at capacity.", "The Jet A-1 ceiling of 380000.00 bbl, reached first."]'::jsonb, 2, 'The plan''s lists name one unit at capacity, the Diesel hydrotreater, and two crudes at their availability, Forcados and Brass River. The crude unit is not on the unit list, Bonny Light is not on the crude list, and every product reads false at its ceiling, Jet A-1 at 288354.84 of 380000.00 bbl.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 10, 'A jet floor of 1000000 is set with its ceiling raised to 1200000. What status does the plan return?', '["infeasible", "invalid, for a floor above its ceiling", "unbounded, since the raised ceiling opens the month", "optimal, with Jet A-1 held at 380000.00 bbl"]'::jsonb, 0, 'Each number is sound on its own, and the engine returns the status infeasible: "No plan satisfies these constraints. A product floor is probably beyond what the crudes and units can make." A floor above its own ceiling is the invalid case.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 11, 'A gasoline floor of 500000 is typed above its ceiling of 450000. Why is this refused before any plan is attempted?', '["No crude mix makes 500000 bbl of reformate, which planning finds out.", "The two numbers alone can never both be met.", "Its ceiling is reset to 500000 first.", "A floor is read only when its ceiling is blank, so the floor is dropped."]'::jsonb, 1, 'The engine sees the conflict from the two numbers, so the status is invalid: "Gasoline has a minimum demand above its maximum." The jet case needs the plan to find there is no answer.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 12, 'Every crude availability, unit capacity and demand ceiling is left blank. Which sentence does the engine return?', '["\"No plan satisfies these constraints. A product floor is probably beyond what the crudes and units can make.\"", "\"Naphtha reformer capacity must be zero or more; leave it blank for no limit.\"", "\"The plan needs at least one crude.\"", "\"The plan is unbounded: a product has a price and no demand ceiling, or a crude has no availability limit and no cost.\""]'::jsonb, 3, 'A blank limit is no limit. With nothing limiting crude and nothing limiting sales, every profitable barrel invites another and there is no best month, so the status is unbounded.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 13, 'The configuration carries no product at all. What does the engine return?', '["Status invalid: \"The plan needs at least one product to sell.\"", "Status optimal, with a margin made of crude cost and unit operating cost alone.", "Status unbounded, since no demand ceiling limits the month.", "Status invalid: \"The plan needs at least one crude.\""]'::jsonb, 0, 'The engine names what it cannot trust. No product at all and no crude at all are each refused with their own sentence, before any plan is attempted.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 14, 'Which product earns ABUA''s largest revenue line?', '["Gasoline, 38464364.52, the highest price.", "Fuel oil, 37354612.90.", "Diesel (ULSD), 66076400.00.", "Jet A-1, 30421435.48, sold at 105.5000 a barrel."]'::jsonb, 2, 'The product table prints Diesel (ULSD) at 630500.00 bbl and 66076400.00. Gasoline carries the highest price, 111.0000, on a smaller volume.'),
  ('refinery', 'intermediate', 'module', 'm03-reading-the-plan', 15, 'Gasoline sells 346525.81 bbl. Which row of the stream balance accounts for that volume?', '["Naphtha: made 407677.42, consumed 407677.42 by the reformer.", "Reformate: made 346525.81, placed 346525.81, surplus 0.00.", "Kero: made 288354.84, placed 288354.84, surplus 0.00.", "Offgas: made 103638.71, placed 0.00, surplus 103638.71."]'::jsonb, 1, 'Gasoline''s recipe is reformate 1.0000, and the reformate row places all 346525.81 bbl it makes. Naphtha goes to the reformer, kero to Jet A-1, and offgas has no home.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 1, 'What does ABUA''s plan mean by a stream''s marginal value?', '["The revenue the stream earned this month, divided by the barrels of it made.", "The price of the product the stream goes into, read across from the product table.", "The value of one more barrel of that stream arriving from outside, in dollars a barrel.", "The cost of the crude barrels that must be run to make one more barrel of it."]'::jsonb, 2, 'marginalValue is the plan''s value of one more barrel of a stream arriving from outside, in US dollars a barrel. It prices the next barrel, and the crude course teaches the dual it comes from.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 2, 'Which stream prints a marginal value that is the same figure as its only product''s price, in the plan as typed?', '["Kero, 105.5000, beside Jet A-1 at 105.5000.", "Naphtha, 91.4500, beside Naphtha export at 72.5000.", "Gasoil, 94.1016, beside Gasoil export at 89.5000.", "Offgas, 0.0000, beside a product priced at 0.0000."]'::jsonb, 0, 'Kero has one product, Jet A-1, no unit and no surplus, and its value prints 105.5000, Jet A-1''s price. Naphtha and gasoil feed units and print 91.4500 and 94.1016, and offgas has no product at all.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 3, 'Reformate is worth 111.0000, Gasoline''s price. Which reading of the plan lets one more barrel of reformate be sold as Gasoline?', '["Gasoline''s floor of 0.00 obliges the plan to sell every barrel of reformate made.", "Gasoline reads true for at its ceiling, so the next barrel goes to surplus.", "Reformate carries a surplus of 103638.71 bbl waiting to be placed in Gasoline.", "Gasoline reads false for at its ceiling, so the plan can sell one more barrel."]'::jsonb, 3, 'The value is of one more barrel arriving from outside, and Gasoline, reformate''s only product, reads false at its ceiling, selling 346525.81 of 450000.00 bbl. The surplus of 103638.71 bbl belongs to offgas, and reformate''s surplus is 0.00.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 4, 'The plan values naphtha at 91.4500. Which working does the digest print for that figure?', '["Naphtha export''s price of 72.5000, with the reformer''s 2.9000 a barrel added on top.", "What the reformer makes from a barrel at the stream values, less its 2.9000 operating cost.", "Gasoline''s price of 111.0000, less the crude unit''s 1.2500 a barrel of distillation.", "A barrel of Bonny Light (illustrative) at 82.5500, shared over its naphtha yield of 0.2300."]'::jsonb, 1, '0.8500 x 111.0000 + 0.1000 x 0.0000 - 2.9000 = 91.4500. The reformer runs at 97.07 percent, below its capacity, so one more barrel of naphtha goes through it.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 5, 'The Diesel hydrotreater is at capacity. Through which crude does the digest''s working value gasoil at 94.1016?', '["Forcados (illustrative), the crude the plan runs at its full availability.", "Brass River (illustrative), also run at its full availability in the plan.", "Bonny Light (illustrative), which the plan runs only in part.", "None: once the hydrotreater is full, the next barrel of gasoil is valued at Gasoil export''s 89.5000."]'::jsonb, 2, 'One more barrel of gasoil lets the plan run less of the crude it only partly runs. At break-even a barrel of Bonny Light (illustrative), 82.5500 with the crude unit''s 1.2500, equals what its streams are worth, and that gives 94.1016.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 6, 'Why is the step from 400000.00 to 420000.00 bbl of reformer capacity priced at only 2.9773 a barrel?', '["The reformer''s operating cost of 2.9000 a barrel is taken off each barrel of room.", "The step is the first one the digest prints, so it carries no change in margin.", "Gasoline reaches its ceiling inside that step and holds the reformer back.", "The reformer fills partway through the step and reads 97.07 percent at 420000.00 bbl."]'::jsonb, 3, 'The gain is the change in margin, 59545.39, over the change in capacity, 20000.00 bbl. Part of that room is used and part is not, so the figure averages the two stretches.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 7, 'Why does the plan value offgas at 0.0000?', '["No product or unit takes it, so a barrel more only adds to the surplus.", "Its only product, Fuel oil, is sold up to its ceiling for the month.", "The reformer burns it as fuel, and its cost and value cancel out exactly.", "Its yields of 0.0300 and 0.0200 are too small for the plan to put a price on."]'::jsonb, 0, 'Offgas has no product and no unit, and 103638.71 bbl of it is left as surplus. A barrel added to surplus changes nothing in the month''s margin, so its value is 0.0000.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 8, 'A planner knows offgas is burned in the plant''s heaters. What does ABUA''s value of 0.0000 say about that use?', '["That the heaters burn it in the plan, as the unit that offgas feeds.", "Nothing, since the configuration gives offgas no product and no unit to see it through.", "That the reformer takes it back as its feed, at 2.9000 a barrel.", "That the fuel use is priced at Fuel oil''s 59.0000 somewhere else in the plan."]'::jsonb, 1, 'The value is the plan''s value of one more barrel arriving from outside. The stream table prints offgas with no product, no unit and 103638.71 bbl of surplus, so the configuration carries no use for it. The reformer''s feed is naphtha, and Fuel oil''s recipe is residue.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 9, 'Under a jet floor of 300000 and a fuel oil floor of 700000, residue reads 79.6607 while Fuel oil sells at 59.0000. Which reading accounts for it?', '["Fuel oil reaches its ceiling under the two floors, so residue is sent to a dearer home instead.", "The floors lift Fuel oil''s price inside the plan to 79.6607 a barrel for the month.", "The fuel oil floor is met exactly, and residue is valued at Bonny Light''s break-even.", "Residue becomes a feed of the Diesel hydrotreater under the two floors."]'::jsonb, 2, 'The plan sells Fuel oil 700000.00 and the floor is met exactly: true. Bonny Light (illustrative) is the crude only partly run, at 567857.14 bbl, and residue is valued at its break-even, 79.6607.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 10, 'What do naphtha and gasoil read under the jet floor of 300000 and fuel oil floor of 700000?', '["72.5000 and 89.5000, the same figures as their export prices.", "91.4500 and 94.1016, the same figures as in the plan as typed.", "83.6941 and 99.8560, as with the hydrotreater capacity left blank.", "91.4500 and 87.8029, as with the hydrotreater typed as shut."]'::jsonb, 0, 'Under the floors naphtha prints 72.5000 and gasoil 89.5000, the export prices, and the plan now sells Naphtha export 42607.14 and Gasoil export 74035.71. The other options are the values as typed and under the two hydrotreater rows.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 11, 'One column of the stream values moves when the diesel hydrotreater is typed as shut. Which stream, and what does it read?', '["Naphtha, to 83.6941.", "Gasoil, to 89.5000.", "Residue, to 79.6607.", "Gasoil, to 87.8029."]'::jsonb, 3, 'The shut row prints gasoil at 87.8029 and every other stream at its value as typed. That figure is neither the value as typed, 94.1016, nor Gasoil export''s price, 89.5000.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 12, 'Leaving the hydrotreater capacity blank moves the value of a stream the hydrotreater never takes as feed. Which stream, and to what?', '["Gasoil, from 94.1016 to 99.8560.", "Naphtha, from 91.4500 to 83.6941.", "Residue, from 59.0000 to 79.6607.", "Reformate, from 111.0000 to 105.5000."]'::jsonb, 1, 'The blank row prints naphtha at 83.6941, the reformer''s feed. Gasoil also moves, to 99.8560, and gasoil is the hydrotreater''s own feed. A stream''s value is a property of the whole plan.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 13, 'Across all six rows of the digest''s stream values under each change, which streams print one value in every row?', '["Reformate, kero, ulsd and residue.", "Naphtha, reformate, kero and ulsd.", "Reformate, kero, ulsd and offgas.", "Kero, ulsd, residue and offgas."]'::jsonb, 2, 'Reformate prints 111.0000, kero 105.5000, ulsd 104.8000 and offgas 0.0000 in every row. Residue reads 79.6607 under the floors, and naphtha and gasoil move in several rows.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 14, 'The reformer is stepped from its typed 420000.00 bbl to 440000.00 bbl. What margin gain per extra barrel of capacity is printed?', '["0.0000, with the reformer at 92.65 percent.", "2.9773, with the reformer at 97.07 percent.", "7.7559, with the reformer at 100.00 percent.", "59545.39, with the reformer at 92.65 percent."]'::jsonb, 0, 'The margin reads 7077935.48 at 440000.00 bbl, a change of 0.00 over 20000.00 bbl, so the gain per extra barrel is 0.0000, with the reformer at 92.65 percent. 7.7559 and 2.9773 are the two steps up to 420000.00 bbl.'),
  ('refinery', 'intermediate', 'module', 'm04-what-another-barrel-is-worth', 15, 'Between 380000.00 and 400000.00 bbl of reformer capacity, the gain per extra barrel is 7.7559. What do the reformer''s utilisation readings show at both capacities?', '["97.07 percent at both, so part of the room is left empty.", "100.00 percent at both, so each extra barrel of room is used.", "92.65 percent at 400000.00 bbl, so only part of the room is used.", "No utilisation is printed for these steps, only the margins."]'::jsonb, 1, 'The reformer is full at both capacities, and the margin moves from 6863271.83 to 7018390.09, a change of 155118.26 over 20000.00 bbl. Here the reformer is a bottleneck in the plain sense.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 1, 'How does ABUA''s schedule decide how many cargoes a crude arrives in?', '["The crude run divided by the cargo size, rounded down, with any part cargo dropped.", "The crude run divided by the cargo size, rounded up to a whole cargo, at least one.", "One cargo for each week in the period, so five cargoes whatever the crude run.", "The crude''s availability divided by the cargo size, rounded up to a whole cargo."]'::jsonb, 1, 'The digest prints the rule: cargoes = the crude run divided by the cargo size, rounded UP to a whole cargo (at least one). The days between cargoes are the 31 days divided by the cargoes, rounded DOWN.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 2, 'Forcados (illustrative) runs 1100000.00 bbl at a cargo size of 400000.00 bbl, from period start 2027-03-01. What receipts does the schedule make?', '["Two cargoes, 15 days apart, on 2027-03-01 and 2027-03-16.", "Three cargoes, one a week, on 2027-03-07, 2027-03-14 and 2027-03-21.", "One cargo of 1100000.00 bbl on 2027-03-01, part 1 of 1.", "Three cargoes, 10 days apart, on 2027-03-01, 2027-03-11 and 2027-03-21."]'::jsonb, 3, 'Forcados'' crude run over the cargo size prints 2.7500, which rounds up to 3 cargoes, and 31 days over 3 cargoes rounds down to 10 days between them. Each part carries 366666.67 bbl.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 3, 'Bonny Light (illustrative) prints a crude run over the cargo size of 0.8226. What receipts does the schedule make for it?', '["One cargo of 329032.26 bbl on 2027-03-01, part 1 of 1.", "No receipt, because its run is short of one whole cargo.", "One cargo of 400000.00 bbl on 2027-03-01, the full cargo size.", "One cargo of 329032.26 bbl on 2027-03-31, the period''s last day."]'::jsonb, 0, 'The cargo rule rounds up to a whole cargo, at least one, so Bonny Light arrives as rcpt-1: 329032.26 bbl on 2027-03-01, part 1 of 1, with 31 days between cargoes.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 4, 'What value does each of the three Forcados receipts carry?', '["24120000.00, the figure on each Brass River receipt.", "26750322.58, the figure on the Bonny Light receipt.", "28453333.33, its share of the Forcados crude cost.", "85360000.00, the whole Forcados crude cost on each part."]'::jsonb, 2, 'The value of a receipt is its share of that crude''s cost. The plan''s Forcados crude cost is 85360000.00, and each of the three parts, rcpt-2, rcpt-3 and rcpt-4, carries 28453333.33.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 5, 'The same plan is cascaded again at a cargo size of 150000 bbl. What does the digest show changing?', '["The crude receipts stay at 6, and each carries a smaller share of its crude.", "The crude receipts become 15, and the plan''s volumes and margin stay as they were.", "The plan runs less Forcados, since each smaller cargo holds less of the crude.", "The crude receipts become 15, and the margin is solved again for the extra cargoes."]'::jsonb, 1, 'The cargo size changes the schedule and leaves the plan alone. At 150000 bbl Forcados arrives on eight dates from 2027-03-01 to 2027-03-22, and the plan''s crude volumes, costs and margin do not change.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 6, 'What does the value on a cdu run event, 507258.06, stand for?', '["Its share of the crude cost of the barrels that week''s run distils.", "Its share of the revenue from the products that week''s run makes.", "The margin earned on the 405806.45 bbl that the run distils.", "Its share of the crude unit''s operating cost, money the refinery spends."]'::jsonb, 3, 'Receipts carry the crude cost, runs carry the unit operating cost and lifts carry the revenue. The scheduled cdu total is 2536290.32, the crude unit''s operating cost for the month.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 7, 'Where in each week does ABUA''s schedule date a unit run, and where a product lift?', '["Runs on the first day of each week, lifts on the last, the fifth lift on 2027-03-31.", "Both on the first day of each week, from 2027-03-01 through to 2027-03-29.", "Runs on the last day of each week, and lifts on the first day of the next.", "Runs on every day of the period, lifts once at the period''s end, 2027-03-31."]'::jsonb, 0, 'Runs fall on 2027-03-01, 2027-03-08, 2027-03-15, 2027-03-22 and 2027-03-29. Lifts fall on 2027-03-07, 2027-03-14, 2027-03-21, 2027-03-28 and 2027-03-31, the fifth week cut short by the end of the period.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 8, 'What does ABUA''s event table carry for Naphtha export and Gasoil export?', '["Five lifts each of 0.00 bbl, dated with the other products.", "One lift each, on 2027-03-31, the last day of the period.", "No lift at all; the table lifts gasoline, jet, diesel and fuel_oil.", "Five lifts each, valued at 72.5000 and 89.5000 a barrel."]'::jsonb, 2, 'The product lifts, lift-22 to lift-41, are five each for gasoline, jet, diesel and fuel_oil, product lifts 20. Both exports sell 0.00 bbl in the plan and appear in neither the event table nor the totals table.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 9, 'The cdu run dated 2027-03-29 falls in a week cut short by the end of March. What quantity does it carry?', '["None: the short week''s run is folded into the run of 2027-03-22.", "405806.45 bbl, the same as each of the four runs before it.", "2029032.26 bbl, the whole month''s crude in one final run.", "130000.00 bbl, the short week''s share of the crude unit''s month."]'::jsonb, 1, 'The schedule''s events are equal whatever the length of the week they fall in. It does not weight a short week lightly, and 130000.00 bbl is each dht run.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 10, 'What does cascadeToSchedule do when it is called with periodStart left out?', '["It refuses and names the missing period start, as a blank cost is refused.", "It dates the schedule from 2027-03-01, the default period start it carries.", "It returns a schedule of 0 events.", "It reads the machine clock and dates the schedule from that day."]'::jsonb, 3, 'The digest names the argument: cascadeToSchedule reads it when periodStart is left out. The same plan cascaded on two different days would then give two different schedules.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 11, 'ABUA''s schedule is built in seven time zones with the period start passed as the string "2027-03-01". What does the digest print?', '["Every zone''s 41 dates match the UTC run, from 2027-03-01 to 2027-03-31.", "Africa/Lagos and Pacific/Kiritimati start one day early, on 2027-02-28, and the rest match.", "The zones west of Greenwich start one day early, on 2027-02-28.", "Only UTC and Europe/London match; the other five shift by a day."]'::jsonb, 0, 'A period start given as a YYYY-MM-DD string is the same calendar day in every zone. That is how the Suite page passes it and how this digest passes it.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 12, 'The period start is handed over as new Date(2027, 2, 1), a Date built at local midnight. In which zones does the schedule start on 2027-02-28?', '["America/New_York and America/Los_Angeles.", "Pacific/Pago_Pago and Pacific/Kiritimati.", "Africa/Lagos and Pacific/Kiritimati.", "Every zone the digest tried except UTC."]'::jsonb, 2, 'Built at local midnight, the Date gives 2027-02-28 as the first date in Africa/Lagos and Pacific/Kiritimati, and every date matches UTC reads false there. The two American zones and Pago Pago keep 2027-03-01.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 13, 'With the Date built at local midnight, America/New_York starts on 2027-03-01. What does that reading show about the Date form?', '["It is safe everywhere, since New York already crosses the spring clock change inside the period.", "It holds in New York and fails in Lagos, so one zone''s reading proves nothing.", "It fails only in zones whose clocks change during the 31 day period.", "The engine reads the Date''s local calendar day in every zone it runs in."]'::jsonb, 1, 'With the Date form, America/New_York reads 2027-03-01 and matches UTC, while Africa/Lagos and Pacific/Kiritimati read 2027-02-28. New York and Los Angeles cross the spring clock change inside the period and still match, and the engine reads the Date''s UTC calendar day.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 14, 'An infeasible plan is cascaded to a schedule. What comes back?', '["41 events dated from 2027-03-01, each carrying a value of 0.00.", "The plan''s refusal, repeated on every event.", "0 events, with the note \"No optimal plan to cascade.\"", "The last optimal schedule, unchanged until the plan is fixed."]'::jsonb, 2, 'When the plan has no answer there is nothing to spread. A schedule of 0 events says there is no month to read actuals against until the plan is fixed.'),
  ('refinery', 'intermediate', 'module', 'm05-the-schedule', 15, 'Which three things does the engine''s note on ABUA''s schedule name as not modelled?', '["Cargo sizes, unit runs and lifts.", "Crude costs, product prices and unit operating costs.", "Time zones, the clock change and the period start.", "Tank capacity, jetty windows and turnarounds."]'::jsonb, 3, 'The note reads "Tank capacity, jetty windows and turnarounds are not modelled: this is the shape of the month to read actuals against, not a berth-level schedule." A turnaround is entered in the plan, as a unit typed as shut.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'In ABUA''s end to end table, which reading is the month''s margin divided by its total crude?', '["Crude unit utilisation, 78.04 percent.", "Revenue for the month, 172316812.90.", "Gross margin per barrel of crude, 3.4883.", "The marginal value of gasoil, 94.1016."]'::jsonb, 2, 'gross margin per barrel = margin / total crude. The table prints margin 7077935.48, total crude 2029032.26 bbl and gross margin per barrel of crude 3.4883.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Before any figure of ABUA''s plan is read, what do its configuration and status show?', '["Every limit typed, every cost and price present, and the status optimal.", "One unit capacity left blank for no limit, and the status optimal.", "Every limit typed, the jet price left blank, and the status invalid.", "Every limit typed, every cost present, and the status unbounded."]'::jsonb, 0, 'Every crude carries a cost and an availability, every unit a capacity and an operating cost, and every product a price and a ceiling, and the plan as typed returns optimal. A blank price is refused with the status invalid.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'Suppose ABUA''s plan came back infeasible. What would stand where the end to end table''s figures now stand?', '["Stream values of 0.0000 on every stream, and 41 events.", "A margin of 0.00, with the schedule still dated from 2027-03-01.", "The last optimal plan, since the table keeps the one before.", "The engine''s refusal sentence, and a schedule of 0 events."]'::jsonb, 3, 'An infeasible plan is refused with "No plan satisfies these constraints. A product floor is probably beyond what the crudes and units can make." and it cascades to 0 events, with the note "No optimal plan to cascade." No margin or stream value comes back.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'Four limits sit around ABUA''s month. Which one do the plan''s lists name as reached?', '["The crude unit, running 2029032.26 of its 2600000.00 bbl.", "The hydrotreater, running 650000.00 of its own 650000.00 bbl.", "The Diesel (ULSD) ceiling, selling 630500.00 of 750000.00 bbl.", "Bonny Light''s availability, running 329032.26 of 1500000.00 bbl."]'::jsonb, 1, 'Only the Diesel hydrotreater reads 100.00 percent, and it is the one unit the plan lists at capacity. The crude unit reads 78.04 percent, Diesel (ULSD) is below its ceiling, and Bonny Light is not among the crudes at their availability.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'Which three readings in ABUA''s end to end table belong to the schedule?', '["Schedule events 41, unit runs 15 and product lifts 20.", "Schedule events 41, crude receipts 6, first receipt date 2027-03-01.", "Crude receipts 6, weeks in the period 5, last lift date 2027-03-31.", "Total crude 2029032.26, crude receipts 6 and schedule events 41."]'::jsonb, 1, 'The end to end table carries three schedule readings: schedule events 41, crude receipts 6 and first receipt date 2027-03-01. The breakdown into unit runs and product lifts is printed with the schedule itself.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Why does ABUA''s schedule carry product lifts 20?', '["Six products, each lifted in weekly events, less the two exports'' first lifts.", "Five weeks, each with a lift for every one of the crudes received that week.", "Twenty cargoes of product, one for each 400000.00 bbl the refinery makes.", "Four products sell, and each is lifted in 5 weekly events."]'::jsonb, 3, 'Gasoline, Jet A-1, Diesel (ULSD) and Fuel oil sell, each lifted in five weekly events with weeks in the period 5. Naphtha export and Gasoil export sell 0.00 bbl and have no lifts.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'At a cargo size of 400000.00 bbl, how do ABUA''s three crudes make crude receipts 6?', '["Bonny Light 1, Forcados 3 and Brass River 2.", "Bonny Light 2, Forcados 3 and Brass River 1.", "Two cargoes each for all three of the crudes.", "Forcados 3 and Brass River 3, Bonny Light none."]'::jsonb, 0, 'Bonny Light''s 329032.26 bbl arrives as one cargo, Forcados'' 1100000.00 bbl as three and Brass River''s 600000.00 bbl as two, each count rounded up to a whole cargo.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'rcpt-1 carries 329032.26 bbl and 26750322.58. Where does ABUA''s plan print the same two figures?', '["The stream balance: naphtha made and consumed.", "The product table: Gasoline''s volume and revenue.", "The crude table: Bonny Light''s volume and its cost.", "The unit table: the reformer''s throughput and cost."]'::jsonb, 2, 'The crude table prints Bonny Light (illustrative) at 329032.26 bbl costing 26750322.58, and the schedule lands it as one cargo, rcpt-1, part 1 of 1. The reformer runs 407677.42 bbl for 1182264.52, and Gasoline sells 346525.81 bbl for 38464364.52.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Which reading shows a configuration whose crude unit was given a feed?', '["The crude unit reading 78.04 percent, short of its 2600000.00 bbl capacity.", "Total crude and crude unit throughput agreeing to the barrel, printed as true.", "A crude unit operating cost of 0.00 on a month of 2029032.26 bbl of crude.", "The crude unit charging 1.2500 a barrel on every barrel of crude."]'::jsonb, 2, 'In the fed configuration the digest prints crude unit operating cost 0.00, and the crude is still run. The three other options read ABUA as typed: 78.04 percent, the agreement flag true, and 2536290.32 at 1.2500 a barrel.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Of these changes the digest prices around ABUA''s month, which one raises the margin?', '["The reformer stepped from 420000.00 to 440000.00 bbl.", "The crude unit held at 1900000 barrels for the month.", "The jet and fuel oil floors of 300000 and 700000.", "The hydrotreater capacity left blank, for no limit."]'::jsonb, 3, 'The blank hydrotreater prints a margin change of 95572.87. The reformer step to 440000.00 bbl changes the margin by 0.00, the crude unit at 1900000 barrels by -230175.48, and the two floors by -1148089.05.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'The hydrotreater left blank prints a margin change of 95572.87. Over what period does that figure run?', '["One month''s plan, the 31 days from 2027-03-01.", "A year of plans, since a margin is a yearly figure.", "The hydrotreater''s working life, as a return on capital.", "One week, the length of each weekly unit run event."]'::jsonb, 0, 'ABUA is one month''s plan, cascaded from period start 2027-03-01 over 31 days, and each change is that month planned again. Capital is no term in the margin, which is revenue less crude cost less unit operating cost.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'streamModel''s LEDGER names plan, schedule and actual. Which two does ABUA''s month fill?', '["The feasibility screen and its licensing sequence.", "The plan and the schedule it cascades into.", "The stream values and the reformer sweep.", "The seven time zone runs of the schedule."]'::jsonb, 1, 'streamModel.LEDGER is plan, schedule, actual. ABUA is one month''s plan and the schedule cascaded from it; nothing in it is recorded as an actual. The engine''s note calls the schedule "the shape of the month to read actuals against".'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Which way of handing cascadeToSchedule its period start keeps ABUA''s dates the same in every zone and on every day it runs?', '["Leave it out, so the schedule is dated from the day it is built.", "Pass it as a Date at local midnight, as the Suite page does.", "Pass it as a Date, the way the digest''s seven zone run does.", "Pass it as a YYYY-MM-DD string, so no clock or zone can move it."]'::jsonb, 3, 'Left out, the period start is read from the machine clock. A YYYY-MM-DD string is the same calendar day in every zone, and that is how the Suite page and the digest pass it, 2027-03-01 for ABUA. A Date built at local midnight starts on 2027-02-28 in Africa/Lagos and Pacific/Kiritimati.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'Which of ABUA''s streams is valued through a unit that has room?', '["Naphtha, 91.4500, through the reformer at 97.07 percent.", "Gasoil, 94.1016, through the hydrotreater at 100.00 percent.", "Residue, 59.0000, through Fuel oil at its price.", "Offgas, 0.0000, leaving 103638.71 bbl of surplus."]'::jsonb, 0, 'Naphtha''s working runs through the reformer at 97.07 percent: 0.8500 x 111.0000 + 0.1000 x 0.0000 - 2.9000 = 91.4500. With the hydrotreater at 100.00 percent, gasoil is valued at Bonny Light''s break-even; residue has one home in Fuel oil, and offgas has none.'),
  ('refinery', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'Which ABUA figure does the schedule''s totals table print identically in its scheduled and plan columns?', '["The margin, 7077935.48, dated 2027-03-31.", "The crude unit capacity, 2600000.00 bbl.", "The cdu''s 2029032.26 bbl and 2536290.32.", "The offgas surplus of 103638.71 bbl, lifted weekly."]'::jsonb, 2, 'The digest sets the schedule''s totals beside the plan''s for all ten materials, and every row agrees. The cdu row reads 2029032.26 bbl and 2536290.32 in both, so the schedule adds no barrels and loses none.'),
  ('refinery', 'intermediate', 'final', null, 1, 'Which of ABUA''s units takes gasoil as its feed, and what does a barrel of it make?', '["Naphtha reformer, making reformate 0.8500 and offgas 0.1000.", "Diesel hydrotreater, making ulsd 0.9700 and offgas 0.0200.", "Crude distillation, making each crude''s own yields of streams.", "No unit; gasoil goes only to Gasoil export at 89.5000."]'::jsonb, 1, 'The unit table gives the Diesel hydrotreater a feed of gasoil and yields of ulsd 0.9700 and offgas 0.0200, at an operating cost of 1.8000 a barrel.'),
  ('refinery', 'intermediate', 'final', null, 2, 'Which ABUA product carries the recipe residue 1.0000, and at what price?', '["Gasoil export, at 89.5000.", "Naphtha export, at 72.5000.", "Diesel (ULSD), at 104.8000.", "Fuel oil, at 59.0000."]'::jsonb, 3, 'The product table prints Fuel oil at 59.0000 a barrel with a ceiling of 1000000.00 bbl and the recipe residue 1.0000.'),
  ('refinery', 'intermediate', 'final', null, 3, 'What kero yield and cost does ABUA''s configuration give Brass River (illustrative)?', '["Kero 0.1600, at 80.4000 a barrel.", "Kero 0.1500, at 81.3000 a barrel.", "Kero 0.1300, at 77.6000 a barrel.", "Kero 0.2600, at 80.4000 a barrel."]'::jsonb, 0, 'Brass River (illustrative) costs 80.4000 and yields kero 0.1600. 0.1500 and 81.3000 are Bonny Light''s, 0.1300 and 77.6000 Forcados'', and 0.2600 is Brass River''s naphtha yield.'),
  ('refinery', 'intermediate', 'final', null, 4, 'What gross margin per barrel of crude does the plan print with the hydrotreater typed as shut for a turnaround?', '["3.4445", "2.3061", "0.5770", "3.6041"]'::jsonb, 2, 'The shut hydrotreater row prints 0.5770, a change of -2.9113 from the plan as typed. 3.4445 is the blank row, 2.3061 the Forcados cargo cancelled and 3.6041 the crude unit at 1900000 barrels.'),
  ('refinery', 'intermediate', 'final', null, 5, 'A planner means the reformer to have no limit this month. What should its capacity box hold?', '["0, which the plan reads as the absence of a limit.", "-1, which the engine takes as an unlimited unit.", "Its typed 420000.00, which the plan reads as no limit.", "Nothing, since a blank capacity is no limit."]'::jsonb, 3, 'A limit left blank is no limit, and a limit typed as 0 is a limit of zero. A negative capacity is refused with the status invalid, the typed 420000.00 is reported as a capacity of 420000.00, and a blank capacity is reported as the number Infinity.'),
  ('refinery', 'intermediate', 'final', null, 6, 'Which change to ABUA''s configuration returns the status unbounded?', '["The reformer capacity typed as -1 in place of a blank.", "Every crude availability, unit capacity and demand ceiling left blank.", "A jet floor of 1000000 with its ceiling raised to 1200000.", "The cost of Forcados (illustrative) left blank."]'::jsonb, 1, 'With nothing limiting crude and nothing limiting sales there is no best month. The -1 capacity and the blank cost are invalid, and the jet floor of 1000000 is infeasible.'),
  ('refinery', 'intermediate', 'final', null, 7, 'Which margin belongs to the row where the Forcados availability is typed 0?', '["5929846.43", "6847760.00", "4030705.04", "424264.71"]'::jsonb, 2, 'The cancelled cargo prints a margin of 4030705.04, a change of -3047230.44. 5929846.43 is the jet and fuel oil floors, 6847760.00 the crude unit at 1900000 barrels and 424264.71 the hydrotreater shut.'),
  ('refinery', 'intermediate', 'final', null, 8, 'What throughput does ABUA''s Naphtha reformer run, against what capacity?', '["407677.42 bbl of 420000.00 bbl, 97.07 percent.", "650000.00 bbl of 650000.00 bbl, 100.00 percent.", "2029032.26 bbl of 2600000.00 bbl, 78.04 percent.", "346525.81 bbl of 450000.00 bbl, below its ceiling."]'::jsonb, 0, 'The unit table prints the reformer at 407677.42 of 420000.00 bbl, 97.07 percent, with an operating cost of 1182264.52. 346525.81 bbl is the Gasoline sold, against Gasoline''s ceiling.'),
  ('refinery', 'intermediate', 'final', null, 9, 'What margin difference does the digest print between the configuration as typed and the one where distillation is no longer feedless?', '["95572.87", "-230175.48", "9614225.81", "2536290.33"]'::jsonb, 3, 'The fed configuration prints a margin of 9614225.81 against 7077935.48, and the digest prints the difference as 2536290.33. The crude unit runs 0.00 bbl and charges 0.00 for distillation.'),
  ('refinery', 'intermediate', 'final', null, 10, 'When distillation is given a feed, which utilisation is printed for it?', '["null", "0.00 percent", "78.04 percent", "100.00 percent"]'::jsonb, 1, 'The digest prints the crude unit utilisation in that configuration as 0.00 percent, with the unit running 0.00 bbl. A null utilisation belongs to a unit whose capacity is blank or typed as 0.'),
  ('refinery', 'intermediate', 'final', null, 11, 'What crude cost does ABUA''s plan print for Brass River (illustrative), on what volume?', '["85360000.00 on 1100000.00 bbl.", "26750322.58 on 329032.26 bbl.", "48240000.00 on 600000.00 bbl.", "24120000.00 on 300000.00 bbl."]'::jsonb, 2, 'The crude table prints Brass River (illustrative) at 600000.00 bbl, its whole availability, costing 48240000.00. 24120000.00 on 300000.00 bbl is one of its two receipts in the schedule.'),
  ('refinery', 'intermediate', 'final', null, 12, 'Which total crude and crude unit utilisation does the plan print once the jet and fuel oil floors are added?', '["2267857.14 bbl, at 87.23 percent.", "1900000.00 bbl, at 100.00 percent.", "2082608.70 bbl, at 80.10 percent.", "1747826.09 bbl, at 67.22 percent."]'::jsonb, 0, 'The floors row prints total crude 2267857.14 bbl and crude unit utilisation 87.23 percent. The crude unit runs every barrel of crude, so its throughput is the total crude.'),
  ('refinery', 'intermediate', 'final', null, 13, 'Which of ABUA''s units carries an operating cost of 1182264.52 for the month?', '["Diesel hydrotreater, 650000.00 bbl at 1.8000.", "Crude distillation, 2029032.26 bbl at 1.2500.", "Naphtha reformer, 420000.00 bbl at 2.9000.", "Naphtha reformer, 407677.42 bbl at 2.9000."]'::jsonb, 3, 'The unit table prints the reformer''s operating cost as 1182264.52 on its throughput of 407677.42 bbl. 420000.00 bbl is its capacity, which the plan does not fill.'),
  ('refinery', 'intermediate', 'final', null, 14, 'How much Jet A-1 does ABUA''s plan sell, against what ceiling?', '["380000.00 of 380000.00 bbl, at its ceiling true.", "288354.84 of 380000.00 bbl, at its ceiling false.", "324178.57 of 380000.00 bbl, at its ceiling false.", "288354.84 of 450000.00 bbl, at its ceiling false."]'::jsonb, 1, 'The product table prints Jet A-1 at 288354.84 bbl against its ceiling of 380000.00, earning 30421435.48. 324178.57 bbl is the Jet A-1 sold under the jet and fuel oil floors.'),
  ('refinery', 'intermediate', 'final', null, 15, 'What revenue does Fuel oil earn in ABUA''s plan, on what volume?', '["38464364.52 on 346525.81 bbl.", "66076400.00 on 630500.00 bbl.", "37354612.90 on 633129.03 bbl.", "30421435.48 on 288354.84 bbl."]'::jsonb, 2, 'Fuel oil sells 633129.03 bbl for 37354612.90. The other three rows are Gasoline, Diesel (ULSD) and Jet A-1.'),
  ('refinery', 'intermediate', 'final', null, 16, 'Once made, consumed and placed barrels are netted, what is recorded as surplus?', '["Stream held in tank at the month''s end for the next month''s plan.", "Stream the plan chose to sell at export prices outside the recipes.", "Stream the units consumed beyond their capacity, printed as over.", "Stream nobody found a home for, what is made less consumed less placed."]'::jsonb, 3, 'The balance takes each stream''s make, subtracts what units consume and what products place, and keeps the remainder at zero or above. Offgas alone carries one here, 103638.71 bbl.'),
  ('refinery', 'intermediate', 'final', null, 17, 'Which of ABUA''s products sells 0.00 bbl in the plan as typed?', '["Fuel oil", "Gasoil export", "Jet A-1", "Gasoline"]'::jsonb, 1, 'The product table prints Gasoil export and Naphtha export at 0.00 bbl, and the stream balance shows gasoil and naphtha consumed in full by the hydrotreater and the reformer.'),
  ('refinery', 'intermediate', 'final', null, 18, 'Which status does each of the five changes in the digest''s change table return?', '["infeasible", "invalid", "optimal", "unbounded"]'::jsonb, 2, 'The hydrotreater shut, the hydrotreater left blank, the crude unit at 1900000 barrels, the Forcados cargo cancelled and the jet and fuel oil floors each return optimal, with a margin and a gross margin per barrel.'),
  ('refinery', 'intermediate', 'final', null, 19, 'The gross margin per barrel''s change from the plan as typed prints -1.1822 on one row. Which row?', '["The Forcados cargo cancelled.", "The diesel hydrotreater typed as shut.", "The jet and fuel oil floors together.", "The crude unit held at 1900000 barrels."]'::jsonb, 0, 'Losing the Forcados cargo moves the ratio from 3.4883 to 2.3061. Of the other rows, the turnaround reads -2.9113, the floors -0.8736 and the capped crude unit 0.1158.'),
  ('refinery', 'intermediate', 'final', null, 20, 'Once the two floors are added, how many barrels of Fuel oil does the month sell?', '["633129.03 bbl, as in the plan as typed.", "1000000.00 bbl, its ceiling.", "324178.57 bbl, the Jet A-1 figure.", "700000.00 bbl, the floor met exactly."]'::jsonb, 3, 'The digest prints Fuel oil 700000.00 under the floors, and the fuel oil floor is met exactly: true. 633129.03 bbl is Fuel oil''s volume as typed and 1000000.00 bbl its ceiling.'),
  ('refinery', 'intermediate', 'final', null, 21, 'How many dollars is one more barrel of ulsd worth to ABUA''s month?', '["105.5000, the same figure as Jet A-1''s price.", "104.8000, the same figure as Diesel (ULSD)''s price.", "94.1016, the figure the plan gives gasoil.", "111.0000, the same figure as Gasoline''s price."]'::jsonb, 1, 'The stream table prints ulsd at 104.8000 beside its one product, Diesel (ULSD) at 104.8000, with no unit and no surplus. 105.5000 is kero''s value, 94.1016 gasoil''s and 111.0000 reformate''s.'),
  ('refinery', 'intermediate', 'final', null, 22, 'With the crude unit at 1900000 barrels, what do naphtha and gasoil read?', '["83.6941 and 99.8560.", "91.4500 and 94.1016.", "91.4500 and 99.8560.", "72.5000 and 89.5000."]'::jsonb, 2, 'The crude unit row prints naphtha 91.4500, as typed, and gasoil 99.8560. 83.6941 and 99.8560 are the blank hydrotreater and the cancelled cargo, and 72.5000 and 89.5000 the floors.'),
  ('refinery', 'intermediate', 'final', null, 23, 'In the digest''s gasoil working, which yield divides the break-even?', '["Bonny Light''s gasoil yield, 0.3100.", "Bonny Light''s residue yield, 0.2800.", "The hydrotreater''s ulsd yield, 0.9700.", "Forcados'' gasoil yield, 0.3400."]'::jsonb, 0, '(82.5500 - 0.2300 x 91.4500 - 0.1500 x 105.5000 - 0.2800 x 59.0000 - 0.0300 x 0.0000) / 0.3100 = 94.1016. Under the floors the residue yield, 0.2800, is the divisor in residue''s working.'),
  ('refinery', 'intermediate', 'final', null, 24, 'Under the jet and fuel oil floors, which crude is only partly run, and how much of it?', '["Forcados (illustrative), run at 1100000.00 bbl under the floors.", "Brass River (illustrative), run at 600000.00 bbl under the floors.", "Bonny Light (illustrative), run at 329032.26 bbl as typed.", "Bonny Light (illustrative), run at 567857.14 bbl under the floors."]'::jsonb, 3, 'Under the floors the plan runs Bonny Light (illustrative) 567857.14, Forcados (illustrative) 1100000.00 and Brass River (illustrative) 600000.00. 329032.26 bbl is Bonny Light''s run in the plan as typed.'),
  ('refinery', 'intermediate', 'final', null, 25, 'What margin does the digest print with the reformer''s capacity at 400000.00 bbl?', '["6863271.83", "7018390.09", "7077935.48", "6847760.00"]'::jsonb, 1, 'The sweep prints 6863271.83 at 380000.00 bbl, 7018390.09 at 400000.00 and 7077935.48 at 420000.00 and above. 6847760.00 is the crude unit at 1900000 barrels.'),
  ('refinery', 'intermediate', 'final', null, 26, 'Inside the solved plan, which row''s dual gives each stream value, and with what sign?', '["An average of the prices of the products it enters.", "The crude cost divided by the stream''s yield.", "The negated dual of the stream''s balance row.", "A unit''s operating cost added to its product price."]'::jsonb, 2, 'marginalValue is the negated dual of the stream''s balance row. The crude course teaches what a dual is. This course reads the stream values the plan prints.'),
  ('refinery', 'intermediate', 'final', null, 27, 'How much Gasoil export leaves the refinery when jet and fuel oil floors are set?', '["74035.71 bbl", "0.00 bbl", "250000.00 bbl", "42607.14 bbl"]'::jsonb, 0, 'The floors row sells Gasoil export 74035.71 and Naphtha export 42607.14. As typed, both sell 0.00, and 250000.00 bbl is Gasoil export''s ceiling.'),
  ('refinery', 'intermediate', 'final', null, 28, 'On what date does ABUA''s second Brass River cargo arrive, from period start 2027-03-01?', '["2027-03-11, as rcpt-3.", "2027-03-21, as rcpt-4.", "2027-03-15, as run-9.", "2027-03-16, as rcpt-6."]'::jsonb, 3, 'Brass River arrives in two parts of 300000.00 bbl, rcpt-5 on 2027-03-01 and rcpt-6 on 2027-03-16, 15 days apart. rcpt-3 and rcpt-4 are Forcados receipts, and run-9 is a cdu run.'),
  ('refinery', 'intermediate', 'final', null, 29, 'What quantity does each reformer run event carry?', '["130000.00 bbl", "81535.48 bbl", "405806.45 bbl", "69305.16 bbl"]'::jsonb, 1, 'Each of the five reformer events, run-12 to run-16, prints 81535.48 bbl. 130000.00 bbl is each dht run, 405806.45 bbl each cdu run and 69305.16 bbl each gasoline lift.'),
  ('refinery', 'intermediate', 'final', null, 30, 'What value does each diesel lift carry?', '["7470922.58", "6084287.10", "13215280.00", "7692872.90"]'::jsonb, 2, 'Each diesel lift moves 126100.00 bbl and carries 13215280.00, its share of the Diesel (ULSD) revenue. The others are the fuel_oil, jet and gasoline lifts.'),
  ('refinery', 'intermediate', 'final', null, 31, 'At a cargo size of 150000 bbl, what is the last Forcados receipt date the digest prints?', '["2027-03-22, after seven earlier Forcados dates.", "2027-03-21, as at the 400000.00 bbl cargo size.", "2027-03-19, the last of eight Forcados dates.", "2027-03-31, the last day of the 31 day period."]'::jsonb, 0, 'At 150000 bbl the Forcados dates run 2027-03-01, 2027-03-04, 2027-03-07, 2027-03-10, 2027-03-13, 2027-03-16, 2027-03-19 and 2027-03-22. 2027-03-21 is the last Forcados receipt at 400000.00 bbl.'),
  ('refinery', 'intermediate', 'final', null, 32, 'How many days apart are the Brass River cargoes at a cargo size of 400000.00 bbl?', '["10", "31", "5", "15"]'::jsonb, 3, 'Brass River''s run over the cargo size prints 1.5000, so 2 cargoes, and the 31 days divided by 2 rounds down to 15. Forcados'' cargoes are 10 days apart and Bonny Light''s single cargo prints 31.'),
  ('refinery', 'intermediate', 'final', null, 33, 'With the string period start, what last event date does the schedule print in Pacific/Pago_Pago?', '["2027-03-29, the date of the last runs.", "2027-03-31, as in every other zone.", "2027-03-28, the fourth week''s lifts.", "2027-02-28, a day into February."]'::jsonb, 1, 'With the string form, UTC, Africa/Lagos, Pacific/Kiritimati, Europe/London, America/New_York, America/Los_Angeles and Pacific/Pago_Pago all end on 2027-03-31. 2027-02-28 appears only with the Date form.'),
  ('refinery', 'intermediate', 'final', null, 34, 'In the engine''s note, what is ABUA''s schedule for?', '["a berth plan for the terminal''s jetty desk", "a tank by tank inventory plan for the month", "\"the shape of the month to read actuals against\"", "a turnaround calendar for each of the units"]'::jsonb, 2, 'The engine names tank capacity, jetty windows and turnarounds as not modelled, so none of the three plans in the other options can be read from it. What it is for, in its own words, is reading actuals against the month''s shape.'),
  ('refinery', 'intermediate', 'final', null, 35, 'What does the engine read from a Date object passed as the period start?', '["Its UTC calendar day.", "The calendar day where it runs.", "The machine clock''s current day.", "The first day of its UTC month."]'::jsonb, 0, 'The engine reads a Date''s UTC calendar day, so the answer depends on the zone: built at local midnight, Africa/Lagos and Pacific/Kiritimati start on 2027-02-28.'),
  ('refinery', 'intermediate', 'final', null, 36, 'What first receipt date does ABUA''s end to end table print?', '["2027-03-11, a Forcados cargo.", "2027-03-07, the first lifts.", "2027-02-28, a Lagos Date run.", "2027-03-01, the period start."]'::jsonb, 3, 'The first receipt date is the period start, 2027-03-01, where Bonny Light, Forcados and Brass River each land a cargo. 2027-03-07 is the first lift and 2027-02-28 the Date form''s first date in Africa/Lagos.'),
  ('refinery', 'intermediate', 'final', null, 37, 'The hydrotreater''s runs are run-17 to run-21. What value does the totals table give them for the month?', '["1182264.52, the value of the reformer runs.", "1170000.00, the same as its plan value.", "234000.00, the value of a single dht run.", "4888554.84, all three units'' operating cost."]'::jsonb, 1, 'The dht row prints 650000.00 bbl and 1170000.00 in both columns, the hydrotreater''s operating cost for the month. 1182264.52 is the reformer row, 234000.00 one dht run event and 4888554.84 the plan''s unit operating cost.'),
  ('refinery', 'intermediate', 'final', null, 38, 'Which schedule events carry ABUA''s revenue?', '["The crude receipts.", "The unit runs.", "The product lifts.", "Receipts and runs."]'::jsonb, 2, 'A lift''s value is its share of that product''s revenue: 7692872.90 on each gasoline lift and 7470922.58 on each fuel_oil lift, for example.'),
  ('refinery', 'intermediate', 'final', null, 39, 'What do the schedule''s totals table print for diesel?', '["630500.00 bbl and 66076400.00, in both columns.", "630500.00 bbl scheduled against 750000.00 bbl planned.", "126100.00 bbl and 13215280.00, in both columns.", "650000.00 bbl and 1170000.00, in both columns."]'::jsonb, 0, 'The diesel row reads 630500.00 bbl and 66076400.00 scheduled and planned. 126100.00 bbl and 13215280.00 are one lift, and 650000.00 bbl and 1170000.00 the dht''s month.'),
  ('refinery', 'intermediate', 'final', null, 40, 'Forcados (illustrative) is offered to the plan at which price a barrel?', '["81.3000", "80.4000", "72.5000", "77.6000"]'::jsonb, 3, 'The crude table prices Forcados (illustrative) at 77.6000 a barrel with 1100000.00 bbl available. 81.3000 is Bonny Light''s cost, 80.4000 Brass River''s and 72.5000 the price of Naphtha export.'),
  ('refinery', 'intermediate', 'final', null, 41, 'What naphtha yield does Forcados (illustrative) carry?', '["0.2300", "0.2600", "0.1600", "0.1300"]'::jsonb, 2, 'Forcados (illustrative) yields naphtha 0.1600 and kero 0.1300 in the crude yield table, so 0.1300 is the kero column. Bonny Light yields 0.2300 naphtha and Brass River 0.2600.'),
  ('refinery', 'intermediate', 'final', null, 42, 'How many unit run events does ABUA''s schedule make?', '["15, five weekly runs for each of the three units.", "5, one a week for the crude unit alone.", "20, five weekly runs for each of four units.", "6, one run for each crude cargo received."]'::jsonb, 0, 'With weeks in the period 5, each of the cdu, the reformer and the dht runs in five equal events, unit runs 15. The 20 is the product lifts and the 6 the crude receipts.');
